package com.riskguard.transaction.service;
import com.riskguard.transaction.api.dto.DashboardDtos; import com.riskguard.transaction.domain.*; import com.riskguard.transaction.repository.TransactionRepository; import java.math.BigDecimal; import java.math.RoundingMode; import java.util.*; import java.util.stream.Collectors; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional;
@Service public class DashboardService { private final TransactionRepository transactions; public DashboardService(TransactionRepository transactions){this.transactions=transactions;}
 @Transactional(readOnly=true) public DashboardDtos.Summary summary(UUID userId,boolean elevated){List<Transaction> all=elevated?transactions.findAll():transactions.findAllByCustomerUserId(userId,org.springframework.data.domain.Pageable.unpaged()).getContent(); long total=all.size(); long approved=count(all,TransactionStatus.APPROVED), review=count(all,TransactionStatus.REVIEW), blocked=count(all,TransactionStatus.BLOCKED); BigDecimal avg=all.stream().map(Transaction::getRiskScore).filter(Objects::nonNull).reduce(BigDecimal.ZERO,BigDecimal::add); long scored=all.stream().filter(t->t.getRiskScore()!=null).count(); avg=scored==0?BigDecimal.ZERO:avg.divide(BigDecimal.valueOf(scored),4,RoundingMode.HALF_UP); BigDecimal fraud=total==0?BigDecimal.ZERO:BigDecimal.valueOf(blocked).divide(BigDecimal.valueOf(total),4,RoundingMode.HALF_UP); List<DashboardDtos.StatusCount> volume=all.stream().collect(Collectors.groupingBy(t->t.getStatus().name(),Collectors.counting())).entrySet().stream().map(e->new DashboardDtos.StatusCount(e.getKey(),e.getValue())).sorted(Comparator.comparing(DashboardDtos.StatusCount::status)).toList(); List<DashboardDtos.MerchantCount> merchants=all.stream().collect(Collectors.groupingBy(Transaction::getMerchant,Collectors.counting())).entrySet().stream().sorted(Map.Entry.<String,Long>comparingByValue().reversed()).limit(5).map(e->new DashboardDtos.MerchantCount(e.getKey(),e.getValue())).toList(); return new DashboardDtos.Summary(total,approved,review,blocked,avg,fraud,volume,List.of(),merchants);}
 private static long count(List<Transaction> all,TransactionStatus s){return all.stream().filter(t->t.getStatus()==s).count();}
}
